 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelTriu {
public:
    __aicore__ inline KernelTriu() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t rows, int64_t cols, int64_t diagonal,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->rows = rows;
        this->cols = cols;
        this->diagonal = diagonal;
        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(tmpBuf, tileLength * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int64_t N = this->cols;
        int64_t diag = this->diagonal;
        int64_t tLen = this->tileLength;
        int64_t blkLen = this->blockLength;

        int64_t processed = 0;
        while (processed < blkLen) {
            // Compute the global index of the current element
            // xGm/yGm are already offset, so xGm[processed] = global[gOffset + processed]
            // We need (row, col) in the original 2D tensor for the mask decision
            int64_t globalIdx = this->getGlobalOffset() + processed;
            int64_t row = globalIdx / N;
            int64_t col = globalIdx % N;

            // First column in this row to keep (triu semantics)
            int64_t keepStart = (row + diag > 0) ? (row + diag) : 0;

            // Elements remaining in this row (from col to N-1)
            int64_t rowEnd = (row + 1) * N;
            int64_t rowRemaining = rowEnd - globalIdx;

            // Maximum we can process in this step (bounded by tile and row boundary)
            int64_t segLen = (tLen < rowRemaining) ? tLen : rowRemaining;
            if (segLen > blkLen - processed) {
                segLen = blkLen - processed;
            }

            if (col < keepStart) {
                // Current position is in the zero region of this row
                // Limit segment to the zero region boundary
                int64_t boundary = keepStart - col;
                if (boundary < segLen) {
                    segLen = boundary;
                }
                CopyProcessZero(processed, segLen);
            } else {
                // Current position is in the keep region of this row
                CopyProcessKeep(processed, segLen);
            }
            processed += segLen;
        }
    }

private:
    __aicore__ inline int64_t getGlobalOffset()
    {
        // Reconstruct the global offset from xGm base address
        // Since GlobalTensor is a view, we track it implicitly
        int64_t blockIdx = AscendC::GetBlockIdx();
        // This is an approximation; we rely on the fact that xGm is already offset
        // The correct approach is to store gOffset during Init
        return this->gOffset;
    }

    // Process a tile in the zero region: fill output with zeros
    __aicore__ inline void CopyProcessZero(int64_t progress, int64_t len)
    {
        AscendC::LocalTensor<T> outLocal = outQueueZ.AllocTensor<T>();
        AscendC::Duplicate<T>(outLocal, (T)0, static_cast<uint32_t>(len));
        outQueueZ.EnQue(outLocal);

        AscendC::LocalTensor<T> outDone = outQueueZ.DeQue<T>();
        AscendC::DataCopyExtParams cp;
        cp.blockCount = 1;
        cp.blockLen = static_cast<uint32_t>(len * sizeof(T));
        cp.srcStride = 0;
        cp.dstStride = 0;
        cp.reserve = 0;
        AscendC::DataCopyPad(yGm[progress], outDone, cp);
        outQueueZ.FreeTensor(outDone);
    }

    // Process a tile in the keep region: copy input to output
    __aicore__ inline void CopyProcessKeep(int64_t progress, int64_t len)
    {
        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedLen = ((len + alignNum - 1) / alignNum) * alignNum;

        // Step 1: CopyIn — read from input GM to inQueue UB
        {
            AscendC::LocalTensor<T> inLocal = inQueueX.AllocTensor<T>();
            AscendC::DataCopyExtParams cp;
            cp.blockCount = 1;
            cp.blockLen = static_cast<uint32_t>(len * sizeof(T));
            cp.srcStride = 0;
            cp.dstStride = 0;
            cp.reserve = 0;
            AscendC::DataCopyPad(inLocal, xGm[progress], cp);
            inQueueX.EnQue(inLocal);
        }

        // Step 2: Pass data from inQueue to outQueue (UB→UB)
        {
            AscendC::LocalTensor<T> inDone = inQueueX.DeQue<T>();
            AscendC::LocalTensor<T> outLocal = outQueueZ.AllocTensor<T>();
            AscendC::DataCopy(outLocal, inDone, static_cast<uint32_t>(alignedLen));
            outQueueZ.EnQue(outLocal);
            inQueueX.FreeTensor(inDone);
        }

        // Step 3: CopyOut — write from outQueue UB to output GM
        {
            AscendC::LocalTensor<T> outDone = outQueueZ.DeQue<T>();
            AscendC::DataCopyExtParams cp;
            cp.blockCount = 1;
            cp.blockLen = static_cast<uint32_t>(len * sizeof(T));
            cp.srcStride = 0;
            cp.dstStride = 0;
            cp.reserve = 0;
            AscendC::DataCopyPad(yGm[progress], outDone, cp);
            outQueueZ.FreeTensor(outDone);
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t gOffset;
    int64_t rows;
    int64_t cols;
    int64_t diagonal;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void triu(
    GM_ADDR x, GM_ADDR y,
    int64_t rows, int64_t cols, int64_t diagonal,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength,
    int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelTriu<half> op;
        op.Init(x, y, rows, cols, diagonal, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelTriu<float> op;
        op.Init(x, y, rows, cols, diagonal, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
